function _museStripLineNum(line, shouldStrip) {
  let s = String(line || '').trim();
  if (!s) return '';
  if (shouldStrip) {
    s = s.replace(/^(?:scene|cảnh|shot|ảnh|image|video|prompt)?\s*\d+\s*[\.\:\-\)]\s*/i, '').trim();
  }
  return s;
}

function _museNaturalSort(a, b) {
  const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });
  return collator.compare(String(a?.name || a || ''), String(b?.name || b || ''));
}

function _museReadFileAsBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const res = String(reader.result || '');
      const comma = res.indexOf(',');
      resolve({
        base64: comma >= 0 ? res.slice(comma + 1) : res,
        mime: file.type || 'image/png',
        dataUrl: res
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function _museTimeStr() {
  const d = new Date();
  return [d.getHours(), d.getMinutes(), d.getSeconds()].map((n) => String(n).padStart(2, '0')).join(':');
}

