      i2vPromptText: saved?.i2vPromptText ?? '',
      i2vPrefix: saved?.i2vPrefix ?? '',
      i2vSuffix: saved?.i2vSuffix ?? '',
      i2vStripNum: saved?.i2vStripNum !== false,
